{
  "revised_script": {
    "hook": "You open a message you swore you'd delete—and don't look away.",
    "curiosity": "What happens when the past slips back into your fingers? You've told yourself you're done, yet here it is: a message from someone you once loved, once hurt, once forgot.",
    "psychological_mechanism": "The brain doesn't erase memories—it archives them. Rereading old messages is a way of revisiting a version of yourself that still believed in something. It's not about the message, but the mirror it holds up to your present self.",
    "realization": "You're not chasing the past. You're trying to understand the present. Every reread is a question: Who am I now? What did I learn? What still lingers?",
    "final_line": "The message is just a door. You decide where it leads."
  },
  "edits": [
    {
      "where": "hook",
      "change": "Replaced the generic opening with a vivid, emotionally charged scenario.",
      "why": "The original hook was too factual and lacked emotional urgency. A strong hook must land quickly and hook the viewer emotionally."
    },
    {
      "where": "curiosity",
      "change": "Replaced the generic 'research shows' and 'normal' language with a more poetic and introspective question.",
      "why": "The original curiosity section was too clinical and failed to create a loop that the viewer must close. A good curiosity section invites the viewer to think and engage."
    },
    {
      "where": "psychological_mechanism",
      "change": "Replaced the 'research shows' and 'normal' language with a deeper psychological insight that explains the behavior without diagnosing the viewer.",
      "why": "The original section was too shallow and relied on external authority. A good psychological mechanism must explain the behavior from within, without judgment or certainty."
    },
    {
      "where": "realization",
      "change": "Replaced the passive, dismissive tone with a reflective and empowering realization.",
      "why": "The original realization was too dismissive and failed to connect the behavior to the viewer's current emotional state. A good realization must make the viewer feel seen and understood."
    },
    {
      "where": "final_line",
      "change": "Replaced the generic sign-off with a memorable, poetic line that lingers.",
      "why": "The original final line was a standard call to action and failed to leave a lasting impression. A good final line must stick and provoke thought."
    }
  ],
  "self_scores": {
    "hook_strength": 9,
    "open_loop": 10,
    "midpoint_turn": 9,
    "final_line_stick": 10
  }
}
